/* MoveWise service worker (generated by scripts/build.mjs).
 * Precaches every built file so the app runs fully offline after the first load.
 * No network request is made for anything outside this origin. */
const VERSION = '__VERSION__';
const CACHE = 'movewise-' + VERSION;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' })))),
    // No skipWaiting() here: a new version waits until the person chooses to reload, so a running page never
    // loses the hashed engine-worker file it still refers to.
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('movewise-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // never touch cross-origin requests
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      // Navigations fall back to the cached shell so deep links work offline.
      if (req.mode === 'navigate') return caches.match('./index.html').then((r) => r || caches.match('./'));
      return fetch(req);
    }),
  );
});

self.addEventListener('message', (event) => {
  const d = event.data;
  if (d && d.type === 'SKIP_WAITING') self.skipWaiting();
  if (d === 'version') event.source && event.source.postMessage({ type: 'version', version: VERSION });
});
